-- =====================================================================
--  Gravitas · Contatos com Prefeituras — dados iniciais (MySQL)
--  Santa Cruz do Sul e Uruguaiana, levantamentos de 20–21/10/2026.
--
--  Rode DEPOIS de 01-schema.sql. Pode ser rodado de novo sem duplicar:
--  o ON DUPLICATE KEY UPDATE atualiza o cadastro e NÃO toca em status,
--  responsável nem notas — o trabalho da equipe fica preservado.
--
--  Convertido do arquivo que a versão Supabase usava:
--    insert into public.X  ->  INSERT INTO contatos_X
--    true / false          ->  1 / 0
--    on conflict ... excluded.c  ->  ON DUPLICATE KEY UPDATE c=VALUES(c)
-- =====================================================================

SET NAMES utf8mb4;

-- Seed: Santa Cruz do Sul e Uruguaiana (levantamentos de 20–21/10/2026). Rode DEPOIS de schema.sql.
-- Pode ser rodado de novo sem duplicar: usa ON CONFLICT para atualizar os dados cadastrais e preserva status, responsável e notas.
START TRANSACTION;
ON DUPLICATE KEY UPDATE `nome`=VALUES(`nome`), `uf`=VALUES(`uf`), `populacao`=VALUES(`populacao`), `prefeito`=VALUES(`prefeito`), `vice`=VALUES(`vice`), `presidente_camara`=VALUES(`presidente_camara`), `cadeiras_camara`=VALUES(`cadeiras_camara`), `ordem`=VALUES(`ordem`), `resumo`=VALUES(`resumo`);
ON DUPLICATE KEY UPDATE `cidade_id`=VALUES(`cidade_id`), `grupo`=VALUES(`grupo`), `orgao`=VALUES(`orgao`), `cargo`=VALUES(`cargo`), `nome`=VALUES(`nome`), `partido`=VALUES(`partido`), `telefone`=VALUES(`telefone`), `whatsapp`=VALUES(`whatsapp`), `email`=VALUES(`email`), `endereco`=VALUES(`endereco`), `rede_social`=VALUES(`rede_social`), `obs_fonte`=VALUES(`obs_fonte`), `foto`=VALUES(`foto`), `ordem`=VALUES(`ordem`), `prioritario`=VALUES(`prioritario`), `vinculado_a`=VALUES(`vinculado_a`);
commit;
